    part(2,1,'Microsoft Defender Security Baseline');route('Endpoint security → Security baselines → Microsoft Defender for Endpoint Security Baseline');h('Basics');table([('Name','Security Baseline - Defender for Endpoint'),('Description','Microsoft-recommended security settings for Defender for Endpoint')]);h('Configuration settings');p('Bekijk de standaardconfiguratie van de baseline. Behoud de standaardwaarden, behalve:');table([('BitLocker → Allow Warning For Other Disk Encryption','Disabled')]);p('Deze instelling voorkomt een conflict met de afzonderlijke BitLocker-policy die je in oefening 3 maakt.');h('Scope tag');p('Pharmacy. Verwijder de scope tag Default wanneer die automatisch werd toegevoegd.');h('Assignment');p('Wijs de baseline toe aan dyn-Windows-Devices.');endpart()
