    part(2,3,'Windows Firewall-policy');route('Endpoint security → Firewall → Create Policy');h('Profiel');table([('Platform','Windows'),('Profile','Windows Firewall')]);h('Basics');table([('Name','Firewall - Defender Configuration'),('Description','Enables the firewall for all network profiles')]);h('Configuration settings');p('Gebruik indien nodig het zoekveld om de instellingen terug te vinden.')
