    part(5,6,'De certificaatinschrijving controleren',True);p('Synchroniseer SEA-DEV1 en geef het toestel tijd om het certificaat aan te vragen. Controleer via PowerShell of een certificaat van de Issuing CA aanwezig is:');code(r'''Get-ChildItem -Path Cert:\LocalMachine\My |
    Where-Object { $_.Issuer -like "*Contoso Issuing*" } |
    Format-List Subject, Issuer, DnsNameList, EnhancedKeyUsageList, NotAfter''');p('Controleer:');table([('Issuer','CN=Contoso Issuing Certificate Authority'),('DnsNameList','SEA-DEV1.contoso.com'),('EnhancedKeyUsageList','Client Authentication'),('NotAfter','geldige toekomstige vervaldatum')]);p('Controleer het certificaat ook grafisch:');raw('<ol>');
    for item in ['Start mmc.exe.','Voeg de snap-in Certificates toe.','Selecteer Computer account.','Selecteer Local computer.','Ga naar Certificates (Local Computer) → Personal → Certificates.','Controleer of het device authentication-certificaat aanwezig en geldig is.']: raw('<li>'+escape(item)+'</li>')
    raw('</ol>');endpart();endexercise()

    exercise(6,'Je controleert de globale beveiligingsstatus van de omgeving, onderzoekt eventuele bedreigingen en test de impact van een bestaande Conditional Access-policy.')
    part(6,1,'Microsoft Defender Secure Score',True);route('Microsoft Defender portal → Exposure management → Secure Score');h('Overview');p('Controleer:');ul(['de behaalde score;','de maximaal mogelijke score;','het globale scorepercentage.']);h('Recommended actions');p('Bekijk configuratiewijzigingen waarmee de Secure Score kan worden verhoogd. Open bijvoorbeeld de actie Encrypt all BitLocker-supported drives. Bekijk de beschrijving en remediation guidance.');h('History');p('Controleer:');ul(['eerdere scorewijzigingen;','datum en tijd;','activiteit;','resulterende punten;','categorie;','aan wie de wijziging werd toegeschreven.']);h('Metrics & trends');p('Bekijk de evolutie van de security posture doorheen de tijd.');endpart()
    part(6,2,'Threat detections en alerts',True);route('Microsoft Defender portal → Investigation & response → Incidents & alerts → Alerts');p('Controleer bij beschikbare alerts:');ul(['Severity','Alert title','Affected devices','Status']);p('Open indien mogelijk een alert en bekijk:');ul(['Alert story','Evidence','Recommended actions']);p('Een nieuwe labomgeving kan nog geen security alerts bevatten. Dat is geen fout.');endpart()
    part(6,3,'Conditional Access testen met What If',True);h('Situatie');p('In een eerdere lab werd de policy CA - Require compliant device (Pharmacy pilot) gemaakt in Report-only mode. Je controleert nu de scope en test welke impact de policy zou hebben. Je schakelt de policy niet in.');route('Microsoft Entra admin center → Entra ID → Conditional Access → Policies');p('Open CA - Require compliant device (Pharmacy pilot).');h('Configuratie controleren');table([('Users or agents included','sg-Intune-Pilot-Users'),('Users or agents excluded','het gebruikte Global Administrator-account'),('Target resources','All resources'),('Grant','Require device to be marked as compliant'),('Enable policy','Report-only')]);h('What If uitvoeren');p('Ga terug naar de lijst met Conditional Access-policies en open What If. Configureer:');table([('Identity type','Users'),('User','een pilootgebruiker, bijvoorbeeld Megan Bowen'),('Target type','Cloud apps'),('Cloud app','een Microsoft 365-cloudapp'),('Device platform','Windows'),('Client app','Mobile apps and desktop clients - Modern authentication')]);p('Voer de analyse uit. Controleer of CA - Require compliant device (Pharmacy pilot) verschijnt onder de policies die van toepassing zouden zijn. Controleer bij de grant controls: Require compliant device.');p('Als de policy ook voor een gebruiker buiten de pilootgroep van toepassing zou zijn, moet de assignment scope worden nagekeken.');warning('Laat de policy op Report-only staan. Schakel ze niet in, omdat niet-conforme labtoestellen anders gebruikers kunnen blokkeren tijdens de volgende labs.');endpart();endexercise()

    raw('<details class="disclosure keypoints lab-outcome" id="lab04-eindresultaat"><summary>Eindresultaat · Wat je hebt gerealiseerd</summary><div class="disclosure-content">');p('In deze lab heb je:');ul(['Microsoft Defender for Endpoint gekoppeld aan Microsoft Intune;','Windows-toestellen via een EDR-policy onboarded;','een Microsoft Defender Security Baseline geïmplementeerd;','Microsoft Defender Antivirus geconfigureerd;','Windows Firewall voor Domain, Private en Public profielen geconfigureerd;','ASR-regels in Block mode toegepast op de pilootgroep;','ASR-regels in Audit mode toegepast op de bredere omgeving;','BitLocker met centrale recovery key-opslag geconfigureerd;','Microsoft Tunnel Gateway op Ubuntu geïnstalleerd;','een Tunnel Server Configuration en Site gemaakt;','een VPN-profiel voor iOS/iPadOS gemaakt;','een Root CA en Issuing CA met Microsoft Cloud PKI gemaakt;','trusted certificate- en SCEP-profielen geïmplementeerd;','certificaatinschrijving op een beheerd toestel gecontroleerd;','Microsoft Defender Secure Score en security alerts onderzocht;','de impact van een Conditional Access-policy met What If getest zonder de policy af te dwingen.']);raw('</div></details><a class="button secondary" href="#labs">↑ Naar Praktijklabo’s</a></article>')
    return '\n'.join(out)
